{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile against a plain light background, combining the head, fur, and paws of a brown bear with the glossy, dark brown segmented exoskeleton of a beetle or isopod. Its entire back, sides, neck, shoulders and legs are encased in shiny, overlapping armor plates, with a single large curved horn rising from the top of its head. The bear's brown fur is visible on the head, lower sides, and paws, while the rest of the body is covered by the dark, reflective chitinous shell with distinct segmentation and small oval openings along the lower flank.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with light tan muzzle, black nose, small brown eyes, and dense brown fur",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "a single large, glossy dark brown to black, sickle-shaped horn with sharp serrations along the inner curve, smooth and reflective",
      "where": "arising from the top center of the head and curving upward and backward high above the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown bear ears",
      "where": "on the top sides of the head, flanking the base of the horn and partially edged by dark head plates"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy mammalian legs encased in glossy dark brown segmented armor with large domed shoulder and thigh plates and smaller overlapping plates on the lower segments",
      "where": "under the body, two forelegs at the front and two hind legs at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four bear-like paws with brown fur and visible dark claws on the toes",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "shell",
      "looks_like": "a continuous glossy dark brown exoskeleton forming a domed, segmented carapace with overlapping transverse bands and larger smooth plates over the shoulders and neck",
      "where": "covering the dorsal surface from the back of the neck to the rear, and extending down the sides"
    },
    {
      "part": "plates",
      "looks_like": "shiny, hard, dark brown to black overlapping plates with reflective highlights and fine ridges; large smooth plates on the back, shoulders and upper legs and smaller banded plates on the lower legs and flanks, with a row of small oval openings along the lower side",
      "where": "over the entire trunk, neck, head cap, and all four legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 0
}
